(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["bs"] = {"ui":{"skip":"Preskoči na sadržaj","back":"← Nazad na AI-gile","lang.button":"Jezik: {name}","lang.dialog":"Odaberi jezik","lang.search":"Traži jezike","lang.none":"Nijedan jezik ne odgovara","lang.notYet":"{name} još nije preveden","theme.aria":"Promijeni temu: svijetla, tamna ili crna","theme.toLight":"Prebaci na svijetlu temu","theme.toDark":"Prebaci na tamnu temu","theme.toBlack":"Prebaci na crnu temu (prava crna, blaga za OLED ekrane)","words.underline":"Podvuci ove riječi na stranici","words.underlineHelp":"Pređi mišem preko riječi s tačkicama ili je dodirni da vidiš šta znači.","index.title":"AI-gile: tvoj AI razvojni tim, na jednoj tabli","index.description":"AI-gile je kanban tabla za AI timove koji programiraju. Rade dok ti spavaš; ti dobiješ jednu kratku hrpu stvari za odluku, testiranje i prihvatanje.","hero.logoAlt":"Ikona AI-gile table","hero.h1.html":"Tvoj AI razvojni tim, na jednoj&nbsp;tabli.","hero.alpha":"🐣 Zatvorena pre-alfa","hero.alphaTitle":"Rano i nedovršeno: hvala što isprobavaš!","hero.lede":"Grade dok ti spavaš. Probudiš se uz jednu kratku hrpu: nekoliko pitanja, nekoliko stvari za testiranje, jedan ili dva ljubičasta dijamanta. Klik, prihvaćeno, nazad na kafu.","dl.windows":"Windows aplikacija","dl.browser":"Pokreni u pregledniku","dl.soon":"Uskoro","dl.notify":"🔔 Javi mi kad se otvori","dl.notifySmall":"Alfa ili beta","hero.secondary":"Agile, ali tim nikad ne treba kafu uz stand-up. (Stand-up ipak održavaju.)","pitch.h2":"AI-gile u onoliko riječi koliko želiš","pitch.lede":"Odaberi dužinu, od jedne riječi do 144. Svaka dužina je poseban opis, napisan baš za tu veličinu. Povuci klizač ili koristi tipke sa strelicama.","pitch.rangeLabel":"Dužina u riječima","pitch.dice":"🎲 druga verzija","pitch.words.one":"{n} riječ","pitch.words.other":"{n} riječi","pitch.letters.one":"{n} slovo","pitch.letters.other":"{n} slova","pitch.chars.one":"{n} znak","pitch.chars.other":"{n} znakova","count.line.html.one":"{n} kartica na tabli upravo sada","count.line.html.other":"{n} kartica na tabli upravo sada","features.aria":"Šta radi","f.pile.h":"Jedna hrpa za tebe","f.pile.html":"<b>Za tebe</b> okuplja sve što čeka na tebe, kroz sve projekte: pitanja, stvari za testiranje, zadatke koje može uraditi samo čovjek. Tvoj red kaže šta je sljedeće i koliko traje.","f.sleep.h":"Timovi koji rade dok ti spavaš","f.sleep.p":"Svaki projekt ima lead i tim AI agenata. Komentariši karticu i tim se budi, odradi posao i vrati ti ga s koracima koje može pratiti i umoran čovjek.","f.tester.h":"Prvo provjerava AI tester","f.tester.p":"Prije nego išta stigne do tebe, tester prođe korake u kopiji aplikacije i pokaže šta je vidio, sa snimkom ekrana. Prelistaj one koje su prošle i prihvati jednim klikom.","f.proof.h":"Dokazi, a ne obećanja","f.proof.p":"Svaka predaja pokazuje šta se promijenilo: datoteke, razlike, snimke ekrana. Ne moraš otvarati svaku aplikaciju da vidiš je li gotovo.","f.chat.h":"Čavrljaj sa svojim leadovima","f.chat.p":"Traka u stilu Discorda: jedna ikona po projektu, ljubičasti dijamanti za ono što treba tebe. Pošalji leadu ideju; pretvorit će je u kartice i plan, uz dugme ✅ Go.","f.tidy.h":"Sam održava red","f.tidy.p":"Srodne kartice se spajaju u jednu, zbrkani naslovi se popravljaju, a provjera tokena drži kod vitkim. Manje stvari između kojih prebacuješ, manje razmišljanja.","f.private.h":"Tvoje, na tvom računaru","f.private.li1":"Tabla radi na tvom vlastitom računaru i odgovara samo tebi.","f.private.li2":"Privatne poruke među ljudima su šifrovane od kraja do kraja.","f.private.li3":"Bez računa, bez trackera, bez kolačića.","f.lang.h":"Na tvom jeziku","f.lang.p":"Preko 120 jezika, od holandskog, velškog i japanskog do gusarskog, Yode i klingonskog, uz brzo prebacivanje na engleski za programerske riječi.","f.service.h":"Od ideje do pravog servisa","f.service.p":"Napravio si s AI-jem nešto što ljudi sada koriste? Označi to kao servis i ploča ti pomaže da ga dobro vodiš: provjere dostupnosti, javna stranica statusa, incidenti s analizom, promjene kojima treba Go, sigurnosne kopije koje se provjeravaju svaki dan. Pomoć te uči svaki korak usput.","tl.aria":"Vremenska crta od prvog razgovora do plana razvoja","tl.h2":"Od prvog četa do onoga što slijedi","tl.lede":"Pravi datumi i vremena, u tvojoj vremenskoj zoni. Poslije danas je plan, bez obećanih datuma.","tl.today":"Danas","tl.planned":"planirano","tl.cards.one":"{n} kartica","tl.cards.other":"{n} kartica","join.h2":"Pridruži se","join.lede":"AI-gile gradi jedan mali čovjek i veliki broj strpljivih agenata. Za sada je privatan, u zatvorenoj alfi s prijateljima. Želiš li probati kad se otvori?","join.btn":"Prijavi interes","join.small":"Poslat ćemo ti e-mail, ništa drugo","footer.tag":"AI-gile. Bez trackera, bez kolačića, bez kafe uz stand-up.","footer.licence":"Poslovna licenca","footer.status":"Status","footer.privacy":"Šta čuvamo","footer.thanks":"Pozivi zahvaljujući ChilledChat","form.sending":"Šaljem…","form.failed":"Nije uspjelo: pokušaj ponovo kasnije.","form.offline":"Nije moguće doći do AI-gile: pokušaj ponovo kasnije.","form.keep":"Ovo koristimo samo da ti odgovorimo, a onda ga brišemo. Bez trackera, bez kolačića.","form.keepLink":"Šta čuvamo","interest.title":"AI-gile: javi mi kad se otvori alfa","interest.description":"Ostavi e-mail da saznaš kad se otvori zatvorena alfa ili beta AI-gile.","interest.h1":"🔔 Javi mi kad se otvori","interest.lede":"AI-gile je u zatvorenoj pre-alfi. Ostavi e-mail i javit ćemo ti se jednom, kad bude mjesta za tebe.","interest.email":"Tvoj e-mail","interest.which":"Koje testiranje?","interest.alpha":"Zatvorena alfa: rano, grubo, mnogo promjena","interest.beta":"Beta: stabilnija, kasnije","interest.both":"Bilo koje, šta prije stigne","interest.submit":"Stavi me na listu","interest.thanks":"Hvala! Na listi si.","licence.title":"AI-gile: poslovna licenca","licence.description":"Koristiš li AI-gile u svom poslu? Zatraži besplatnu poslovnu licencu.","licence.h1":"📜 Poslovna licenca","licence.lede":"Koristiš li AI-gile na poslu? Reci nam ko si i čime se baviš. Ako čini nešto dobro, licenca je besplatna.","licence.company":"Firma","licence.website":"Web stranica","licence.what":"Čime se baviš","licence.how":"Kako pomaže svijetu","licence.email":"E-mail","licence.submit":"Prijavi se","licence.thanks":"Hvala! Odgovorit ćemo e-mailom.","status.title":"AI-gile status","status.h1":"AI-gile status","status.quiet":"Sve mirno","status.intro":"Radi li AI-gile upravo sada? Ova stranica svakih 5 minuta provjerava web stranicu, dijeljenje tabli, pozive i preuzimanje.","status.up":"Radi (odgovorio za {ms} ms)","status.slow":"Nije odgovorio na zadnju provjeru, pokušavamo ponovo","status.down":"Ne radi: nije odgovorio na zadnje dvije provjere","status.svc.web":"Web stranica","status.svc.web.offers":"Ova stranica: šta je AI-gile, i obrazac za interes","status.svc.boards":"Dijeljenje tabli","status.svc.boards.offers":"Javne table, poruke među prijateljima i pozivnice","status.svc.calls":"Pozivi","status.svc.calls.offers":"Glas, video i dijeljenje ekrana u AI-gileu","status.svc.download":"Preuzimanje","status.svc.download.offers":"Windows instaler i linkovi za pozivnice","status.checking":"Provjeravam…","status.offline":"Trenutno nije moguće doći do servisa statusa (pokušavam ponovo)","status.updated":"ažurirano {ago}","status.justNow":"upravo sada","status.min":"prije {n} min","status.hours":"prije {n} h","status.days":"prije {n} d","privacy.title":"AI-gile: šta čuvamo","privacy.h1":"Šta čuvamo","privacy.lede":"Ukratko: samo ono što nam pošalješ, i to ne dugo.","privacy.only":"Samo ono što nam pošalješ: ono što upišeš u obrazac, recimo svoj e-mail. Ništa drugo o tebi.","privacy.sealed":"Zapečaćeno je tako da ga naš server ne može pročitati: u tvom pregledniku prije nego što krene (u starijem pregledniku, čim stigne). Samo ga naša vlastita tabla može otvoriti.","privacy.server":"Briše se sa servera čim stigne do naše table. Sve što je tamo i dalje nakon 30 dana svakako se briše.","privacy.board":"Na našoj tabli ga čuvamo samo dok ti ne odgovorimo, a onda ga i tamo brišemo.","privacy.none":"Bez trackera, bez kolačića, bez analitike.","privacy.local":"Tvoj jezik i izbor svijetle ili tamne teme ostaju u tvom pregledniku. Nikad nam se ne šalju.","privacy.ask":"Želiš da nestane ranije? Odgovori na naš e-mail i reci nam.","live.h2":"Gledajte kako se gradi, uživo","live.caption":"Svaka kartica je skrivena: vidite oblik posla, a ne riječi.","live.watching.one":"uživo: {n} gleda","live.watching.other":"uživo: {n} gleda","live.last.now":"Posljednja kartica premještena je upravo sada","live.last.min.one":"Posljednja kartica premještena je prije {n} min","live.last.min.other":"Posljednja kartica premještena je prije {n} min","live.last.hour.one":"Posljednja kartica premještena je prije {n} sat","live.last.hour.other":"Posljednja kartica premještena je prije {n} sati","live.last.day.one":"Posljednja kartica premještena je prije {n} dan","live.last.day.other":"Posljednja kartica premještena je prije {n} dana","live.offline":"Tabla uživo malo odmara. Navratite uskoro.","live.cols":"Backlog|Za uraditi|U toku|Tim provjerava|Za tvoje testiranje|Za tim|Gotovo","pitch.words.few":"{n} riječi","pitch.letters.few":"{n} slova","pitch.chars.few":"{n} znaka","count.line.html.few":"{n} kartice na tabli upravo sada","tl.cards.few":"{n} kartice"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Roboti.","Delegirano."]},{"n":2,"texts":["Robotski kanban.","Agenti, organizovano.","Ideje, izgrađene."]},{"n":3,"texts":["Kanban za robote.","Ideje postaju funkcije.","Besplatni agentski kanban."]},{"n":5,"texts":["Kanban tabla koju vode agenti.","Ti pišeš kartice. Agenti grade.","Besplatno, lokalno, testirano, pomalo smiješno."]},{"n":8,"texts":["Besplatna kanban tabla na kojoj rade AI agenti.","Napiši ideju. Agenti je grade. Ti prihvataš.","Agile za jednog čovjeka i mnogo strpljivih robota."]},{"n":13,"texts":["Kanban tabla na tvom računaru na kojoj AI agenti preuzimaju kartice.","Napiši ideju. Tim agenata je izgradi, zatim je tester provjeri, a ti kažeš da.","Besplatno, bez računa, bez trackera: tabla, nekoliko robota i ti kao šef."]},{"n":21,"texts":["AI-gile je kanban tabla za rad s AI agentima koji programiraju. Oni preuzimaju kartice; ti ih testiraš i prihvataš.","Svaki projekt dobije lead i tim AI agenata. Komentariši bilo koju karticu i tim odmah prione na posao.","Besplatna, lična tabla zadataka koja radi na tvom vlastitom računaru. Radnici su roboti. Onaj ko kaže da, to si ti."]},{"n":34,"texts":["Ideje stavljaš na tablu. Tim AI agenata ih pretvara u funkcije koje rade, testira ih i vraća ti ih s koracima za isprobavanje. Ništa se ne računa kao gotovo dok ti to ne kažeš.","AI-gile je domaća kanban tabla koju je Rich napravio uz mnogo pomoći agenata kojima sada upravlja. Besplatna je, radi na tvom računaru i dijeli se s prijateljima, ne prodaje se.","Zamisli običnu kanban tablu, s kolonama od Backloga do Gotovo, samo što kartice preuzimaju AI agenti. Javljaju napredak, pitaju kad zapnu i uvijek čekaju tvoj podignuti palac."]},{"n":55,"texts":["AI-gile je kanban tabla na kojoj tim čine AI agenti. Svaki projekt ima lead koji planira posao i pomoćnike koji ga grade. Kad je funkcija spremna, AI tester je isproba i napravi snimak ekrana, a onda sleti na tvoju hrpu. Prihvati je ili napiši komentar pa je prerade.","Počelo je kao način na koji je jedna osoba pratila mnogo AI programerskih sesija odjednom, a izraslo je u pravu tablu. Radi na tvom računaru, ne traži račun i nema trackera. Besplatna je za prijatelje i znatiželjnike. Također je nedovršena, pa računaj na grube ivice i poneko iznenađenje.","Evo poštene verzije. Ideje i dalje moraš imati ti, a rezultate i dalje moraš provjeriti ti. AI-gile radi sve između: drži kartice u redu, budi pravog agenta kad komentarišeš, pokazuje tačno šta se promijenilo i sve to slaže u jednu kratku hrpu za tebe."]},{"n":89,"texts":["AI-gile je besplatna kanban tabla koju pokrećeš na vlastitom računaru. Umjesto ljudi, svaki projekt ima tim AI agenata: lead koji tvoje ideje pretvara u kartice i plan, i pomoćnike koji kartice preuzimaju po prioritetu. Kad je nešto izgrađeno, AI tester slijedi korake testiranja i pokazuje ti šta je vidio. Zatim čeka u jednoj hrpi koja se zove Za tebe. Ti je prihvatiš, ili komentarišeš pa tim pokuša ponovo. Ništa ne stiže do Gotovo bez tebe.","Nekoliko stvari koje možda ne očekuješ. Noćna straža drži kolonu Za uraditi popunjenom dok ti spavaš, birajući kartice kojima ne treba tvoj odgovor. Brojač tokena pokazuje koliko su agenti potrošili danas i ove sedmice, a No Token Mode im kaže da prestanu trošiti. Možeš pisati prijateljima, a privatne poruke su šifrovane od kraja do kraja. Tabla govori oko 120 jezika, uključujući holandski, flamanski, gusarski i klingonski. Ništa od toga ne košta ni feninga, a niko ti to ni ne pokušava prodati.","AI-gile je mali, lični projekt, a ne firma. Rich je htio voditi nekoliko AI programerskih projekata bez otvaranja svake aplikacije da ih provjeri, pa su on i agenti napravili tablu za to, a onda tablu iskoristili da izgrade ostatak sebe. U zatvorenoj je pre-alfi, što znači da radi, uglavnom, za šaku prijatelja. Nema stranice s cijenama, nema newslettera i nema plana rasta. Ako ti zvuči korisno, možeš zatražiti da probaš kad se malo više otvori."]},{"n":144,"texts":["AI-gile je kanban tabla za jednog čovjeka i mnogo AI agenata. Radi na tvom vlastitom računaru i potpuno je besplatna. Dodaješ projekte, a svaki projekt dobije lead i mali tim. Čavrljaš s leadom, pomalo kao na Discordu, i opišeš ideju; lead je pretvara u kartice i plan, pa čeka da pritisneš Go. Tim kartice rješava po prioritetu, koristeći jednostavnu komandnu liniju napravljenu za jezičke modele. Prije nego se išta vrati tebi, AI tester prođe korake u kopiji aplikacije i priloži snimak ekrana. Gotov posao sleti na tvoju hrpu s promijenjenim datotekama i razlikom. Ti ga prihvatiš, ili ostaviš komentar pa se tim probudi i pokuša ponovo. Samo ti možeš premjestiti karticu u Gotovo. Nema računa, nema trackera i nema kolačića, a sve ostaje na tvom računaru.","Otprilike jedan dan s AI-gile. Navečer ostaviš nekoliko komentara: ovo dugme je na pogrešnom mjestu, ta lista bi trebala biti sortirana, može li tamni mod. Odeš spavati. Agenti pročitaju komentare, naprave izmjene, testiraju ih i vrate ti ih. Ako Za uraditi ostane prazno, noćna straža ga puni iz backloga karticama kojima ne treba tvoj odgovor. Ujutro te čeka jedna kratka hrpa: par pitanja i nekoliko stvari za isprobavanje, svaka s koracima koje može slijediti i pospana osoba i sa snimkom ekrana na kojem radi. Prokliktaš se, prihvatiš dobre, a ostale vratiš. Brojač tokena pokazuje šta je sve to potrošilo, a No Token Mode je tu za štedljive sedmice. Onda doručkuješ, a u tome ti agenti još ne mogu pomoći.","Prvo, šta AI-gile nije. Nije startup, nije na prodaju i niko ne prikuplja tvoje podatke. To je besplatna tabla koja radi na tvom računaru, bez računa, bez trackera i bez kolačića. A šta jeste: jedno uredno mjesto na kojem vidiš sve AI programerske projekte odjednom, s timom agenata koji radi kartice i tobom koji donosiš odluke. Spaja srodne kartice, popravlja zbrkane naslove i pazi koliko kod ostaje vitak. Govori oko 120 jezika, od holandskog i flamanskog do gusarskog i klingonskog. Prijatelji mogu pisati jedni drugima, privatno i šifrovano. Napravili su je Rich i veliki broj strpljivih agenata, uglavnom koristeći nju samu. U zatvorenoj je pre-alfi, pa je na mjestima gruba. Ako ti zvuči zabavno, lijepo pitaj i možda uđeš ranije."]}],"quips":{"1":"Jedna riječ. Hrabro. Možda i previše hrabro.","3":"Tri riječi. Već iskrenije od većine stranica proizvoda.","8":"Osam riječi. I dalje kraće od stand-upa.","21":"Dužine su, usput, story pointi. Naravno da jesu.","55":"Pedeset pet riječi. Dvije kartice su završene dok si čitao.","144":"To je ona duga. Nema 233. Agenti su otišli spavati."}},"timeline":{"first-idea.name":"Prva ideja","first-idea.line":"Sasvim prvi razgovor, prije nego što je postojao ijedan red koda.","first-board.name":"Prva tabla","first-board.line":"Tabla koja prati vlastitu izgradnju: kartice, kolone, prevlačenje, projekti.","team-roles.name":"Tim i uloge","team-roles.line":"Profili agenata, šabloni timova, prostori i ko šta radi.","install.name":"Instalacija i izdanja","install.line":"Zip koji prijatelj može instalirati, samoažuriranje, kanali i vraćanje unazad.","usage-saver.name":"Štednja potrošnje","usage-saver.line":"Mjeri koliko koštaju pokretanja, drži kod vitkim, čuvaj svoj limit.","friends.name":"Prijatelji i dijeljenje","friends.line":"Privatne poruke, šifrovani relej, pozivnice, uloge i zajednički projekti.","languages.name":"Jezici","languages.line":"Svaki tekst na ekranu u jezičkoj datoteci, prvo holandski i flamanski.","ai-tester.name":"AI tester","ai-tester.line":"Tester prvi provjerava svaku predaju i pokazuje šta je vidio.","website.name":"Web stranica","website.line":"aigile.lol, teaser i ova vremenska crta.","streaming.name":"Čet i striming","streaming.line":"Discord, Twitch, OBS, streamerski mod, GIF-ovi i emotikoni.","no-ai.name":"Izdanje bez AI-ja","no-ai.line":"Tabla za ljude koji programiraju bez AI-ja, i javne table.","night-watch.name":"Noćna straža","night-watch.line":"Čuvar i Scrum Master drže timove na zadatku dok ti spavaš.","p-more.name":"Sve ostalo","p-more.line":"Manje ideje koje još čekaju svoj red.","p-android.name":"Telefon i Android","p-android.line":"Do svoje table s telefona, a zatim izvorna Android aplikacija.","p-release.name":"Alfa i dalje","p-release.line":"Zatvorena alfa, živa stranica, pa beta.","p-languages.name":"Više jezika","p-languages.line":"Više od stotinu jezika i mod uronjenosti za one koji uče.","p-engines.name":"Više AI motora","p-engines.line":"Odaberi Claude, Codex ili Gemini za svakog agenta.","p-pro.name":"Profesionalna praksa","p-pro.line":"Oznake rizika, kapije za spajanje, kartice incidenata i zaštitne ograde.","p-self.name":"Briga o tebi","p-self.line":"Mod umora, podsjetnici na brigu o sebi i 4:20.","p-servers.name":"Serveri i rast","p-servers.line":"Globalne postavke servera, uloge i planiranje rasta.","p-livestream.name":"Dodaci za striming","p-livestream.line":"Twitch čet, vlastiti emotikoni i javni prikaz uživo."},"words":{"button":"📖 Programerske riječi","h":"📖 Objašnjene riječi","intro":"Riječi na koje nailaziš u AI-gile, običnim jezikom: pravljenje, sigurno mijenjanje, održavanje da radi za ljude koji ga koriste i rad u timu s AI-jem.","search":"Traži riječ…","none":"Nijedna riječ se ne poklapa.","close":"Zatvori","count":{"one":"{count} riječ","other":"{count} riječi"},"groups":[{"id":"build","name":"🛠️ Pravljenje"},{"id":"change","name":"🔀 Sigurno mijenjanje"},{"id":"run","name":"🛎️ Vođenje servisa"},{"id":"team","name":"🤝 Rad u timu (i s AI-jem)"}],"list":[{"id":"repo","g":"build","word":"Repo","text":"Folder projekta s kodom i cijelom historijom commitova, obično čuvan i na GitHubu.","also":["repozitorij","repository"]},{"id":"branch","g":"build","word":"Branch","text":"Zasebna linija rada u kodu, da se mogu praviti promjene bez diranja glavne verzije.","also":["branchevi","branches"]},{"id":"commit","g":"build","word":"Commit","text":"Sačuvan snimak koda, s kratkom bilješkom šta se promijenilo. Uvijek se možeš vratiti na njega.","also":["commitovi","commits"]},{"id":"push","g":"build","word":"Push","text":"Slanje sačuvanih snimaka (commitova) s ovog računara na GitHub, da budu sigurnosno kopirani i podijeljeni."},{"id":"merge","g":"build","word":"Merge","text":"Spajanje promjena iz brancha nazad u glavnu verziju."},{"id":"pr","g":"build","word":"Pull request","text":"Traženje da se promjene brancha provjere i spoje u glavnu verziju.","also":["PR"]},{"id":"refactor","g":"build","word":"Refaktorisanje","text":"Sređivanje koda bez mijenjanja onoga što radi: manje datoteke, jasnija imena, manje ponavljanja."},{"id":"bug","g":"build","word":"Bug","text":"Nešto što ne radi kako treba.","also":["bugovi","bugs"]},{"id":"test","g":"build","word":"Test","text":"Isprobavanje završenog posla da se provjeri radi li ono što je traženo, prije nego što ga prihvatiš.","also":["testovi","tests"],"noTip":1},{"id":"qa","g":"build","word":"QA","text":"Skraćenica za quality assurance (osiguranje kvaliteta): automatske provjere koje se pokreću prije nego što išta ode u produkciju. Kad je QA crven, nešto nije prošlo i ne može u produkciju dok se to ne popravi.","also":["provjere kvaliteta","osiguranje kvaliteta","quality checks"]},{"id":"deploy","g":"change","word":"Deploy","text":"Puštanje nove verzije uživo, na primjer na server gdje je ljudi koriste."},{"id":"release","g":"change","word":"Izdanje","text":"Imenovan paket završenog posla koji zajedno ide u produkciju, s kratkim bilješkama o tome šta se promijenilo. 🚀 Izdanja pišu bilješke iz završenih kartica.","also":["izdanja","release"]},{"id":"rollback","g":"change","word":"Vraćanje unazad","text":"Povratak na posljednju verziju koja je radila kad nova pravi probleme. U AI-gile to pravi listu za provjeru od koraka za poništavanje zapisanih na svakoj promjeni.","also":["vrati unazad","rollback","roll back"]},{"id":"live","g":"change","word":"Produkcija","text":"Prava verzija koju ljudi koriste, za razliku od kopije za isprobavanje. Programeri kažu i production ili da je nešto „live“.","also":["uživo","production","live"],"noTip":1},{"id":"change","g":"change","word":"Promjena","text":"Planirana promjena nečega na šta se ljudi oslanjaju, prvo zapisana: šta, zašto, rizik, kada i kako je poništiti. Započni jednu sa 🔀 Podnesi promjenu.","also":["promjene","zahtjev za promjenu","change request"],"noTip":1},{"id":"risk","g":"change","word":"Rizik","text":"Nešto što bi moglo poći po zlu, ocijenjeno po tome koliko je vjerovatno i koliko bi bilo loše. ⚠️ Rizici ih drže na jednoj listi, s najvišom ocjenom prvo, svaki s datumom za ponovni pregled.","also":["rizici","registar rizika"]},{"id":"chgwin","g":"change","word":"Prozor za promjene","text":"Vrijeme kada promjene smiju u produkciju, recimo mirno utorak navečer. Izvan prozora kartica promjene ne može se završiti, osim ako je hitno.","also":["prozori za promjene","change window"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"Brzo glasanje neposredno prije nego što promjena ode u produkciju: svako ko mora odobriti kaže Go ili No go. Ide dalje samo kad se slože.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Odobrenje","text":"Čekanje na „da“ prije nego što posao počne. Kartica koju podnese prijatelj, ili promjena, čeka u ✅ Odobrenja dok je ne odobriš ili odbiješ.","also":["odobrenja","approval"]},{"id":"quiettime","g":"change","word":"Mirno vrijeme","text":"Period, poput strima, demonstracije ili noći, kad ništa ne ide u produkciju. Timovi nastavljaju raditi i testirati, ali odlazak u produkciju čeka da se završi. Negdje drugo se zove zamrzavanje promjena.","also":["mirna vremena","zamrzavanje promjena","change freeze"]},{"id":"service","g":"run","word":"Servis","text":"Nešto što si napravio i na šta se ljudi oslanjaju, poput web stranice ili aplikacije, o čemu se brine da nastavi raditi. Označi „Ovaj projekat je servis“ i reci šta nudi, ko ga koristi i ko je dežuran.","also":["servisi","usluga","service"]},{"id":"uptime","g":"run","word":"Provjera dostupnosti","text":"Automatska provjera, svakih nekoliko minuta, da tvoj servis još odgovara. Ako ne uspije nekoliko puta zaredom, AI-gile sam otvara karticu incidenta.","also":["dostupnost","uptime","uptime check"]},{"id":"statuspage","g":"run","word":"Stranica statusa","text":"Javna stranica koja pokazuje radi li servis (zeleno, narandžasto ili crveno) s najnovijom viješću, da ljudi koji ga koriste mogu provjeriti umjesto da pitaju.","also":["stranice statusa","status page"]},{"id":"incident","g":"run","word":"Incident","text":"Nešto što je upravo sada pokvareno za ljude koji to koriste, kao kad stranica ne radi. Kartica 🔥 incidenta preskače red: da ponovo proradi dolazi prvo.","also":["incidenti","incidencija"]},{"id":"major","g":"run","word":"Veliki incident","text":"Veliki incident: pogođeno mnogo ljudi, ili su novac ili podaci u opasnosti. Jedno dugme stavlja sve timove na njega (roj), budi onoga ko je dežuran i traži novost o stanju svakih 30 minuta.","also":["veliki incidenti","velika incidencija","major incident"]},{"id":"oncall","g":"run","word":"Dežurstvo","text":"Biti onaj ko se javlja kad se nešto pokvari, čak i noću. Svaki servis ima dežurnog člana tima kojeg prvog bude za njegove incidente.","also":["dežuran","na dežurstvu","on call","on-call"]},{"id":"replyby","g":"run","word":"Vrijeme za odgovor","text":"Koliko dugo kartica smije čekati prvi odgovor, recimo sat za incident. Nakon toga dobije crveni sat, da ništa ne bude tiho zaboravljeno. Zove se i cilj odgovora.","also":["vremena za odgovor","cilj odgovora","response target"]},{"id":"postmortem","g":"run","word":"Analiza nakon incidenta","text":"Kratak osvrt nakon incidenta: šta se desilo, šta je pomoglo i šta promijeniti, bez okrivljavanja ikoga. Incident se ne može zatvoriti bez nje.","also":["post-mortem","postmortem","revizija nakon incidenta"]},{"id":"problem","g":"run","word":"Problem","text":"Skriveni uzrok iza jednog ili više incidenata. Kartica 🧩 problema grupiše incidente koji se stalno vraćaju, da se uzrok pronađe i zauvijek popravi.","also":["problemi"],"noTip":1},{"id":"rootcause","g":"run","word":"Osnovni uzrok","text":"Pravi razlog zašto se nešto pokvarilo, a ne samo ono što si vidio da ne valja. Popravi osnovni uzrok i incident se prestaje vraćati.","also":["osnovni uzroci","root cause"]},{"id":"workaround","g":"run","word":"Privremeno rješenje","text":"Način da stvari rade dok pravo rješenje ne bude spremno, recimo ponovno pokretanje nečega kad zapne. Zapisuje se na kartici problema da niko ne mora ponovo smišljati.","also":["privremena rješenja","workaround"]},{"id":"knownerror","g":"run","word":"Poznata greška","text":"Problem čiji je uzrok jasan i koji ima privremeno rješenje, ali još nije popravljen. 🧩 Poznate greške ih navode, da svi koriste privremeno rješenje umjesto da ponovo kopaju.","also":["poznate greške","known error"]},{"id":"runbook","g":"run","word":"Runbook","text":"Uputstva korak po korak za popravljanje poznate vrste problema, da se svaki put uradi isto i brzo. Nakon velikog incidenta tim ti može predložiti jedan da ga odobriš.","also":["runbookovi","priručnik"]},{"id":"backup","g":"run","word":"Sigurnosna kopija","text":"Sačuvana kopija tvojih podataka od ranije, na koju se možeš osloniti ako se nešto izgubi ili ošteti. AI-gile svaki dan pravi sigurnosnu kopiju tvojih ploča.","also":["sigurnosne kopije","bekap","backup"]},{"id":"restore","g":"run","word":"Vraćanje","text":"Vraćanje podataka iz sigurnosne kopije. Sigurnosna kopija se zaista računa tek kad znaš da se može vratiti, pa je vrijedi isprobati s vremena na vrijeme.","also":["vraćanje podataka","vraćeno","restore"]},{"id":"backlog","g":"team","word":"Backlog","text":"Ideje i posao koji još nisu planirani. Na tome se ništa ne radi dok se ne premjesti u Za uraditi."},{"id":"sprint","g":"team","word":"Sprint","text":"Kratak period rada (često sedmica ili dvije) s dogovorenim skupom kartica koje treba završiti.","also":["sprintovi","sprints"]},{"id":"standup","g":"team","word":"Stand-up","text":"Brza provjera: šta je svaki član tima uradio, šta radi sljedeće i šta ga zaustavlja.","also":["standup","stand-upovi","stand-ups"]},{"id":"kanban","g":"team","word":"Kanban","text":"Ploča s kolonama (Za uraditi, U toku, Gotovo) na kojoj se kartice kreću slijeva nadesno dok se radi."},{"id":"wip","g":"team","word":"WIP limit","text":"Rad u toku: najviše kartica koje jedna kolona treba držati, da tim završava stvari prije nego što započne nove.","also":["WIP"]},{"id":"dod","g":"team","word":"Definicija Završeno","text":"Kratka timska lista šta „gotovo“ znači, recimo testirano i objašnjeno, prije nego što ti se kartica preda. Njen blizanac, Definicija Spremno, kaže kad je kartica dovoljno jasna da se počne.","also":["Definicija Spremno","Definition of Done","Definition of Ready"]},{"id":"testpile","g":"team","word":"Gomila testova","text":"Završene kartice koje čekaju da ih isprobaš, jedna za drugom. Prihvati jednu ili je vrati s bilješkom, i dolazi sljedeća.","also":["gomile testova","test pile"]},{"id":"retro","g":"team","word":"Retro","text":"Osvrt na to kako tim radi, da se dogovori jedna stvar koja se može bolje. U AI-gile retro predlaže promjenu u načinu rada tima, a ti kažeš Go ili Još ne.","also":["retrospektiva","retrospektive","retrospective"]},{"id":"peerreview","g":"team","word":"Recenzija kolega","text":"Drugi par očiju: drugi AI provjerava posao svake kartice prije nego što stigne do tebe, pa prođe manje grešaka.","also":["pregled koda","peer review","code review"]},{"id":"swarm","g":"team","word":"Roj","text":"Svi na palubu: svaki tim ostavlja ostali posao da pomogne na jednom hitnom projektu dok se ne riješi. Ostali projekti u međuvremenu čekaju.","also":["swarm","swarming"]},{"id":"scrummaster","g":"team","word":"Scrum Master","text":"Onaj ko drži posao u pokretu: primijeti zaglavljene kartice, pogura timove i podsjeti te šta čeka. U AI-gile Lead Scrum Master to radi za sve projekte.","also":["Lead Scrum Master"]},{"id":"agent","g":"team","word":"Agent","text":"AI koji sam radi na zadatku: čita kod, pravi promjene, pokreće provjere i javlja rezultat.","also":["agenti","agents"]},{"id":"token","g":"team","word":"Token","text":"Jedinica u kojoj se broji korištenje AI-ja: otprilike nekoliko slova teksta pročitanih ili napisanih. Manje tokena, više plana ostaje.","also":["tokeni","tokens"]},{"id":"hook","g":"team","word":"Hook","text":"Mala komanda koja se sama izvršava u određenom trenutku, npr. kad počne AI sesija, da tim čuje tvoje komentare.","also":["hookovi","hooks"]}]}};
